//! `observe`, `persist` and `bounds` against `tests/vectors/oracle/*.json`, generated by
//! `gen_oracle.py` from `shortwin_sim.py` v0.4.1 with its default switches (ARCHITECTURE
//! §8.1, §9 M0b).
//!
//! Units call the sim's own methods on synthetic states. Every comparison is exact: this
//! crate reproduces the sim's integer arithmetic (floor divisions throughout, `reprice`'s
//! ceiling root), so no tolerance is needed. The whole-market traces (observation,
//! persistence, references, `max_in` and settlement together) are in `settle_traces.rs`.
//!
//! Vector encoding: whitespace-separated decimal tokens, `-` for `None`, `1`/`0` for
//! booleans. The layouts are listed in the generator's docstring and next to each parser.
#![allow(clippy::unwrap_used, clippy::arithmetic_side_effects)]

mod common;

use std::collections::HashMap;
use std::fmt::Debug;
use std::str::{FromStr, SplitWhitespace};

use serde::Deserialize;
use shortwin_math::MathError;
use shortwin_math::U256;
use shortwin_math::bounds::{
    ExitParams, expiry_reference, liq_reference, max_in_exp, max_in_liq, pi_ref, ref_depth_cap,
    ref_liquidity, spot_liquidity,
};
use shortwin_math::observe::{
    Bucket, EmaParams, LastBucket, Observation, Ring, RingEntry, VenueChange, integrate,
    rewrite_liquidity, ring_medians, sustained_growth,
};
use shortwin_math::persist::liq_ema_leg;

// ---------------------------------------------------------------------------------------
// Token parsing
// ---------------------------------------------------------------------------------------

struct Toks<'a> {
    it: SplitWhitespace<'a>,
    src: &'a str,
}

impl<'a> Toks<'a> {
    fn new(src: &'a str) -> Self {
        Self {
            it: src.split_whitespace(),
            src,
        }
    }

    fn s(&mut self) -> &'a str {
        self.it
            .next()
            .unwrap_or_else(|| panic!("vector line too short: {}", self.src))
    }

    fn v<T: FromStr>(&mut self) -> T
    where
        T::Err: Debug,
    {
        let s = self.s();
        s.parse()
            .unwrap_or_else(|e| panic!("bad token {s:?} ({e:?}) in: {}", self.src))
    }

    fn opt<T: FromStr>(&mut self) -> Option<T>
    where
        T::Err: Debug,
    {
        match self.s() {
            "-" => None,
            s => Some(
                s.parse()
                    .unwrap_or_else(|e| panic!("bad token {s:?} ({e:?}) in: {}", self.src)),
            ),
        }
    }

    fn b(&mut self) -> bool {
        match self.s() {
            "1" => true,
            "0" => false,
            s => panic!("bad bool {s:?} in: {}", self.src),
        }
    }

    fn bar(&mut self) {
        assert_eq!(self.s(), "|", "separator expected in: {}", self.src);
    }

    fn done(&mut self) {
        assert!(self.it.next().is_none(), "trailing tokens in: {}", self.src);
    }
}

/// `n × (ts p l x y lo hi llo lhi)`, oldest first, as pushed into a fresh ring.
fn parse_ring(t: &mut Toks) -> Ring {
    let n: usize = t.v();
    let mut ring = Ring::default();
    for _ in 0..n {
        ring.push(RingEntry {
            ts: t.v(),
            p: t.v(),
            l: t.v(),
            x: t.v(),
            y: t.v(),
            lo: t.v(),
            hi: t.v(),
            llo: t.v(),
            lhi: t.v(),
            _pad: [0; 8],
        })
        .unwrap();
    }
    ring
}

/// `P_ema L_ema L_slow ema_ts slow_ts count | b_sec b_lo b_hi b_llo b_lhi | lb_sec lb_lo lb_hi | ring`.
fn parse_state(t: &mut Toks) -> Observation {
    let mut o = Observation::default();
    o.ema.price = t.v();
    o.ema.liq = t.v();
    o.ema.liq_slow = t.v();
    o.ema.ts = t.v();
    o.ema.slow_ts = t.v();
    o.ema.count = t.v();
    if let Some(sec) = t.opt() {
        o.bucket = Bucket {
            sec,
            lo: t.v(),
            hi: t.v(),
            llo: t.v(),
            lhi: t.v(),
            _pad: [0; 8],
        };
        assert!(o.bucket.is_open());
    } else {
        for _ in 0..4 {
            assert_eq!(t.s(), "-");
        }
    }
    if let Some(sec) = t.opt() {
        o.last = LastBucket {
            sec,
            lo: t.v(),
            hi: t.v(),
            _pad: [0; 8],
        };
        assert!(o.last.is_set());
    } else {
        for _ in 0..2 {
            assert_eq!(t.s(), "-");
        }
    }
    o.ring = parse_ring(t);
    o
}

fn ring_vec(r: &Ring) -> Vec<RingEntry> {
    r.iter().copied().collect()
}

/// Observation states compare field by field (the ring by content, not by slot layout).
fn assert_state(got: &Observation, want: &Observation, ctx: &str) {
    assert_eq!(got.ema, want.ema, "EMA state, {ctx}");
    assert_eq!(got.bucket, want.bucket, "open bucket, {ctx}");
    assert_eq!(got.last, want.last, "last completed bucket, {ctx}");
    assert_eq!(ring_vec(&got.ring), ring_vec(&want.ring), "ring, {ctx}");
}

