#[derive(Deserialize)]
struct UnitsObserve {
    generator: String,
    integrate: Vec<IntegrateCase>,
    rewrite: Vec<String>,
}

#[derive(Deserialize)]
struct IntegrateCase {
    prm: String,
    t: common::Dec<i64>,
    gap: common::Dec<i64>,
    before: String,
    after: String,
}

/// `Market._integrate` on synthetic states: clamp and bucket corners, dt caps (incl.
/// `dt ≤ 0`), separate slow clocks, wrapping rings, values up to `u128::MAX`, the cached
/// reprojection (incl. `(0, 0)` where it is undefined), the bucket extremes and the gap.
#[test]
fn integrate_matches_sim() {
    let f: UnitsObserve = common::load_vectors("oracle", "units_observe.json");
    assert_eq!(f.generator, "gen_oracle.py");
    assert!(f.integrate.len() >= 150);
    let (mut stepped, mut undefined_xy) = (0, 0);
    for (i, c) in f.integrate.iter().enumerate() {
        let ctx = format!("integrate case {i}");
        let mut t = Toks::new(&c.prm);
        let prm = EmaParams::new(t.v(), t.v(), t.v(), t.v());
        t.done();
        let mut t = Toks::new(&c.before);
        let mut o = parse_state(&mut t);
        t.done();
        let mut t = Toks::new(&c.after);
        let want = parse_state(&mut t);
        t.done();
        let count = o.ema.count;
        let gap = integrate(
            &mut o.ema,
            &mut o.ring,
            &mut o.bucket,
            &mut o.last,
            c.t.0,
            &prm,
        )
        .unwrap();
        assert_eq!(gap, Some(c.gap.0), "pre-roll gap, {ctx}");
        assert_state(&o, &want, &ctx);
        if o.ema.count > count {
            stepped += 1;
            undefined_xy += usize::from(o.ring.newest().unwrap().x == 0);
        }
    }
    assert!(
        stepped >= 100 && undefined_xy >= 3,
        "coverage: {stepped} steps, {undefined_xy} (0, 0)"
    );
}

/// `Market._switch_to_pool` (graduation) and `Market.fast_switch` (Raydium) on synthetic
/// states: every entry's `l`, `llo`, `lhi` and `(x, y)` rewritten, `lo`/`hi` kept, the
/// bucket cleared.
#[test]
fn rewrite_liquidity_matches_sim() {
    let f: UnitsObserve = common::load_vectors("oracle", "units_observe.json");
    assert!(f.rewrite.len() >= 100);
    let mut kinds: HashMap<&str, usize> = HashMap::new();
    for (i, line) in f.rewrite.iter().enumerate() {
        let ctx = format!("rewrite case {i}");
        let mut t = Toks::new(line);
        let kind = t.s();
        let l_new: u128 = t.v();
        t.bar();
        let mut o = parse_state(&mut t);
        t.bar();
        let want = parse_state(&mut t);
        t.done();
        let kind_enum = match kind {
            "g" => VenueChange::Graduation,
            "r" => VenueChange::Raydium,
            k => panic!("unknown kind {k}"),
        };
        rewrite_liquidity(&mut o.ema, &mut o.ring, &mut o.bucket, l_new, kind_enum).unwrap();
        assert_state(&o, &want, &ctx);
        *kinds.entry(kind).or_default() += 1;
    }
    assert!(
        kinds.len() == 2 && kinds.values().all(|&n| n >= 40),
        "{kinds:?}"
    );
}

#[derive(Deserialize)]
struct UnitsRing {
    growth: Vec<String>,
}

/// `ema_growth_bps` and `ring_medians` on arbitrary rings (non-monotone times, falls, huge
/// jumps; `n` from 0 to 8).
#[test]
fn growth_and_medians_match_sim() {
    let f: UnitsRing = common::load_vectors("oracle", "units_ring.json");
    assert!(f.growth.len() >= 200);
    let mut positive = 0;
    for (i, line) in f.growth.iter().enumerate() {
        let ctx = format!("growth case {i}: {line}");
        let mut t = Toks::new(line);
        let n: u8 = t.v();
        let g: U256 = t.v();
        let med: (u128, u128, u128, u128) = (t.v(), t.v(), t.v(), t.v());
        let ring = parse_ring(&mut t);
        t.done();
        let got = sustained_growth(&ring, n).unwrap();
        // The crate saturates g at u64::MAX (every consumer caps it; ECON §8.2).
        assert_eq!(U256::from(got), g.min(U256::from(u64::MAX)), "{ctx}");
        positive += usize::from(got > 0);
        assert_eq!(ring_medians(&ring).unwrap(), med, "{ctx}");
    }
    assert!(positive >= 20, "too few sustained-growth cases: {positive}");
}

