#[derive(Deserialize)]
struct UnitsPersist {
    persist: Vec<String>,
}

/// The liquidation EMA leg of `Market.status` on synthetic rings with a coin-flip
/// predicate per cached `(x, y)` (`fl` newest first).
#[test]
fn liquidation_ema_leg_matches_sim() {
    let f: UnitsPersist = common::load_vectors("oracle", "units_persist.json");
    assert!(f.persist.len() >= 300);
    let mut legs = 0;
    for (i, line) in f.persist.iter().enumerate() {
        let ctx = format!("persist case {i}: {line}");
        let mut t = Toks::new(line);
        let n: u8 = t.v();
        let fl = t.s();
        let leg = t.b();
        let ring = parse_ring(&mut t);
        t.done();
        let mut map = HashMap::new();
        for (e, f) in ring.iter().zip(fl.bytes()) {
            if let Some(old) = map.insert((e.x, e.y), f == b'1') {
                assert_eq!(old, f == b'1', "inconsistent flags, {ctx}");
            }
        }
        let below = |x: u128, y: u128| Ok(*map.get(&(x, y)).expect("queried off the ring"));
        assert_eq!(liq_ema_leg(&ring, below, n), Ok(leg), "{ctx}");
        legs += usize::from(leg);
    }
    assert!(
        legs >= 100 && legs + 100 <= f.persist.len(),
        "coverage: {legs} legs"
    );
}

