#[derive(Deserialize)]
struct UnitsBounds {
    reference: Vec<String>,
    max_in: Vec<String>,
}

/// `Market.exit_reference` (liquidation with the `lo_x·(1 + κ_eff)` cap, and expiry) on
/// synthetic states, incl. stale buckets, κ_base ≥ κ_max and 128-bit overflow of `P_ref`.
#[test]
fn references_match_sim() {
    let f: UnitsBounds = common::load_vectors("oracle", "units_bounds.json");
    assert!(f.reference.len() >= 300);
    let mut kinds: HashMap<&str, usize> = HashMap::new();
    for (i, line) in f.reference.iter().enumerate() {
        let ctx = format!("reference case {i}: {line}");
        let mut t = Toks::new(line);
        let now: i64 = t.v();
        let is_liq = t.b();
        let prm = ExitParams {
            kappa_liq_bps: t.v(),
            kappa_base_bps: t.v(),
            delta_liq_bps: t.v(),
            delta_exp_bps: t.v(),
            kappa_growth_n: t.v(),
            ref_max_age_s: t.v(),
        };
        let mut o = Observation::default();
        o.ema.price = t.v();
        o.ema.liq = t.v();
        o.ema.liq_slow = t.v();
        let l_live: u128 = t.v();
        o.last.sec = t.v();
        o.last.lo = t.v();
        o.last.hi = o.last.lo;
        let kind = t.s();
        let (pref, lb): (Option<u128>, Option<u128>) = (t.opt(), t.opt());
        o.ring = parse_ring(&mut t);
        t.done();
        let got = if is_liq {
            liq_reference(&o.ema, &o.ring, &o.last, now, &prm)
        } else {
            expiry_reference(&o.ema, &o.ring, &o.last, now, &prm)
        };
        match kind {
            "none" => assert_eq!(got, Ok(None), "{ctx}"),
            "overflow" => assert_eq!(got, Err(MathError::Overflow), "{ctx}"),
            "ok" => {
                assert_eq!(got, Ok(pref), "{ctx}");
                // Not a Raydium venue (the generator's `FakeVenue`): no depth cap.
                assert_eq!(
                    ref_liquidity(l_live, &o.ema, &o.ring, None).ok(),
                    lb,
                    "{ctx}"
                );
            }
            k => panic!("unknown result kind {k}"),
        }
        *kinds.entry(kind).or_default() += 1;
    }
    assert!(kinds.get("ok").copied().unwrap_or(0) >= 200, "{kinds:?}");
    assert!(kinds.get("none").copied().unwrap_or(0) >= 50, "{kinds:?}");
    assert!(
        kinds.get("overflow").copied().unwrap_or(0) >= 2,
        "{kinds:?}"
    );
}

/// The `max_in` lines of `Market._buyback_exit` (ECON §8.2 v0.4.1), incl. negative budgets:
/// liquidation without reserve, expiry with rent and fee senior.
#[test]
fn max_in_matches_sim() {
    let f: UnitsBounds = common::load_vectors("oracle", "units_bounds.json");
    assert!(f.max_in.len() >= 500);
    let mut none = 0;
    for line in &f.max_in {
        let mut t = Toks::new(line);
        let got = match t.s() {
            "liq" => {
                let (b, d, v, k, ert): (u64, u16, u64, u64, u64) =
                    (t.v(), t.v(), t.v(), t.v(), t.v());
                max_in_liq(b, d, v, k, ert)
            }
            "exp" => {
                let (b, d, e, fee): (u64, u16, u16, u16) = (t.v(), t.v(), t.v(), t.v());
                let (v, k, r, ert, pi): (u64, u64, u64, u64, u64) =
                    (t.v(), t.v(), t.v(), t.v(), t.v());
                assert_eq!(pi_ref(b, fee), Ok(pi), "{line}");
                max_in_exp(b, d, e, v, k, r, pi, ert)
            }
            k => panic!("unknown kind {k}"),
        };
        let want: Option<u64> = t.opt();
        t.done();
        assert_eq!(got, want, "{line}");
        none += usize::from(want.is_none());
    }
    assert!(none >= 20, "negative budgets: {none}");
}

#[derive(Deserialize)]
struct UnitsRef {
    ref_liquidity: Vec<String>,
    spot_liquidity: Vec<String>,
}

/// `Market.spot_liquidity` (FITS-2 (a); AIR-17): `max(L_live, L_floor)`, `L_floor = min(L_ema,
/// L_mhi)` — the upper median of the bucket liquidity highs — while the post-change guard is set,
/// else `L_ema`, against `bounds::spot_liquidity`.
///
/// `l_live L_ema guard L_spot | ring`.
#[test]
fn spot_liquidity_matches_sim() {
    let f: UnitsRef = common::load_vectors("oracle", "units_ref.json");
    assert!(f.spot_liquidity.len() >= 300);
    let (mut highs, mut ema, mut live) = (0, 0, 0);
    for (i, line) in f.spot_liquidity.iter().enumerate() {
        let ctx = format!("spot_liquidity case {i}: {line}");
        let mut t = Toks::new(line);
        let l_live: u128 = t.v();
        let mut o = Observation::default();
        o.ema.liq = t.v();
        o.ema.guard = u8::from(t.b());
        let want: u128 = t.v();
        assert_eq!(t.s(), "|", "{ctx}");
        o.ring = parse_ring(&mut t);
        t.done();
        assert_eq!(spot_liquidity(l_live, &o.ema, &o.ring), Ok(want), "{ctx}");
        // Coverage: the highs' median binds under the guard, L_ema binds, the live depth binds.
        highs += usize::from(o.ema.guard != 0 && want < o.ema.liq && want > l_live);
        ema += usize::from(want == o.ema.liq && want > l_live);
        live += usize::from(want == l_live);
    }
    assert!(
        highs >= 30 && ema >= 30 && live >= 30,
        "coverage: highs {highs}, ema {ema}, live {live}"
    );
}

/// `L_b` of `Market.exit_reference` alone (M4F-1): the post-change guard on or off and, on a
/// Raydium venue, the cap `Market.ref_depth_cap = ⌊D·10⁴/λ⌋` on the EMA terms — `λ` = 100 %, the
/// pool's `D` itself, since AIR-14 — (binding or not; `L_live` never capped), against
/// `bounds::{ref_depth_cap, ref_liquidity}`.
///
/// `l_live L_ema L_slow guard λ D L_b | ring` (`λ`, `D` `-` off Raydium).
#[test]
fn reference_liquidity_matches_sim() {
    let f: UnitsRef = common::load_vectors("oracle", "units_ref.json");
    assert!(f.ref_liquidity.len() >= 500);
    let (mut capped, mut guarded, mut live) = (0, 0, 0);
    for (i, line) in f.ref_liquidity.iter().enumerate() {
        let ctx = format!("ref_liquidity case {i}: {line}");
        let mut t = Toks::new(line);
        let l_live: u128 = t.v();
        let mut o = Observation::default();
        o.ema.liq = t.v();
        o.ema.liq_slow = t.v();
        o.ema.guard = u8::from(t.b());
        let lam: Option<u32> = t.opt();
        let d: Option<u128> = t.opt();
        let want: u128 = t.v();
        assert_eq!(t.s(), "|", "{ctx}");
        o.ring = parse_ring(&mut t);
        t.done();
        assert_eq!(lam.is_some(), d.is_some(), "{ctx}");
        let cap = lam.zip(d).map(|(lam, d)| ref_depth_cap(d, lam));
        assert_eq!(
            ref_liquidity(l_live, &o.ema, &o.ring, cap),
            Ok(want),
            "{ctx}"
        );
        // Coverage: the cap binds, the guard binds, the live depth is the maximum.
        let uncapped = ref_liquidity(l_live, &o.ema, &o.ring, None).unwrap();
        capped += usize::from(uncapped != want);
        guarded += usize::from(o.ema.guard != 0 && o.ema.liq > want.max(o.ema.liq_slow));
        live += usize::from(want == l_live);
    }
    assert!(
        capped >= 50 && guarded >= 20 && live >= 50,
        "coverage: capped {capped}, guarded {guarded}, live {live}"
    );
}
